// === Tab: node ===
class Node {
	constructor(x, y, depth) {
		this.pos = new p5.Vector(x, y);
		this.depth = depth;

		this.born = frameCount;
		this.lastStimulation = -Infinity;

		this.children = [];
	}

	addChildren(n) {
		for (let i = 0; i < n; i ++) {
			if (frameCount === 0 && Math.random() > 1 / this.depth) continue;
			const coords = random([[1, 0], [1 / 2, rt3 / 2], [-1 / 2, rt3 / 2], [-1, 0], [-1 / 2, -rt3 / 2], [1 / 2, -rt3 / 2]]),
						x = this.pos.x + 50 * coords[0],
						y = this.pos.y + 50 * coords[1];

			if (x < - width / 2 || x > width / 2 || y < -height / 2 || y > height / 2 || nodes.some(node => Math.pow(node.pos.x - x, 2) + Math.pow(node.pos.y - y, 2) < 1)) continue;

			const child = new Node(x, y, this.depth + 1);
			this.children.push(child);
			nodes.push(child);

			if (frameCount === 0) child.addChildren(6);
		}
	}

	stimulate() {
		this.lastStimulation = frameCount;
		if (Math.random() < 0.5) this.addChildren(1);
	}

	draw() {
		push();
		const q = frameCount - this.born;
		stroke(0, q < 50 ? 200 * q / 50 : 200, 0);

		const t = frameCount - this.lastStimulation;
		if (t === 10) {
			for (const child of this.children) child.stimulate();
		}

		for (const child of this.children) {
			push();
			stroke(0, 100, 0);
			line(this.pos.x, this.pos.y, child.pos.x, child.pos.y);
			pop();

			if (t < 10) {
				push();
				strokeWeight(3);
				point(this.pos.x + (child.pos.x - this.pos.x) * t / 10, this.pos.y + (child.pos.y - this.pos.y) * t / 10);
				pop();
			}

			child.draw();
		}

		fill(t < 30 ? 255 * Math.pow(1.1, -t) : 0);
		circle(this.pos.x, this.pos.y, 15);
		pop();
	}
}

